import { index, integer, primaryKey, sqliteTable, text, uniqueIndex } from 'drizzle-orm/sqlite-core'
import { organization, session, user } from './auth-schema'

// Tables for sign-in (user, session, account, verification, rate limits) are generated by Better Auth:
// `pnpm auth:schema`. Our own tables go below.
export * from './auth-schema'

/** Addresses that bounced or complained (from Resend webhooks). We stop emailing them for a while; see suppression.ts. */
export const emailSuppression = sqliteTable('email_suppression', {
  email: text('email').primaryKey(),
  reason: text('reason').notNull(),
  createdAt: integer('created_at').notNull()
})

/** One row per person: their synced preferences (JSON, validated on read) and when they last changed. */
export const preference = sqliteTable('preference', {
  userId: text('user_id')
    .primaryKey()
    .references(() => user.id, { onDelete: 'cascade' }),
  data: text('data').notNull(),
  updatedAt: integer('updated_at').notNull()
})

/** A request to delete an account: it is removed on the scheduled date unless cancelled (then the row is deleted). */
export const accountDeletion = sqliteTable(
  'account_deletion',
  {
    userId: text('user_id')
      .primaryKey()
      .references(() => user.id, { onDelete: 'cascade' }),
    requestedAt: integer('requested_at').notNull(),
    scheduledFor: integer('scheduled_for').notNull(),
    /** SHA-256 of the token in the cancel link, so a leaked database cannot be used to cancel. */
    cancelTokenHash: text('cancel_token_hash').notNull()
  },
  (table) => [index('account_deletion_due_idx').on(table.scheduledFor)]
)

/** One entry in a person's consent ledger (append-only): agreed to or withdrew a purpose, under a policy version. */
export const consent = sqliteTable(
  'consent',
  {
    id: text('id').primaryKey(),
    userId: text('user_id')
      .notNull()
      .references(() => user.id, { onDelete: 'cascade' }),
    purpose: text('purpose').notNull(),
    granted: integer('granted', { mode: 'boolean' }).notNull(),
    policyVersion: text('policy_version').notNull(),
    at: integer('at').notNull()
  },
  (table) => [index('consent_user_idx').on(table.userId, table.at)]
)

/**
 * A feature flag: who gets a feature without a new release. `killed` is the kill switch (off for everyone, at once).
 * Not per person, so it needs no link to a user. Edited with `pnpm flags`.
 */
export const featureFlag = sqliteTable('feature_flag', {
  key: text('key').primaryKey(),
  description: text('description').notNull().default(''),
  killed: integer('killed', { mode: 'boolean' }).notNull().default(false),
  /** Comma separated channels ("stable,beta"); empty means all of them. */
  channels: text('channels').notNull().default(''),
  percent: integer('percent').notNull().default(0),
  updatedAt: integer('updated_at').notNull()
})

/**
 * A request about personal data (export, deletion) with a status and a deadline. No link to the user row and no email:
 * it has to outlive the account it is about, so only a random id, the kind, the status and the dates remain.
 */
export const dataRequest = sqliteTable(
  'data_request',
  {
    id: text('id').primaryKey(),
    /** The user id at the time (a random value; the user row may be gone). */
    subjectId: text('subject_id').notNull(),
    kind: text('kind').notNull(),
    status: text('status').notNull(),
    receivedAt: integer('received_at').notNull(),
    dueAt: integer('due_at').notNull(),
    completedAt: integer('completed_at')
  },
  (table) => [index('data_request_subject_idx').on(table.subjectId, table.receivedAt)]
)

/** One sign-in (a session was created), kept for the activity list and the new-device alert. Pruned after 90 days. */
export const signInEvent = sqliteTable(
  'sign_in_event',
  {
    id: text('id').primaryKey(),
    userId: text('user_id')
      .notNull()
      .references(() => user.id, { onDelete: 'cascade' }),
    at: integer('at').notNull(),
    label: text('label').notNull(),
    ipAddress: text('ip_address'),
    newDevice: integer('new_device', { mode: 'boolean' }).notNull().default(false)
  },
  (table) => [index('sign_in_event_user_at_idx').on(table.userId, table.at)]
)

/** A pending move to a new email address: it happens when the link sent to the new address is used. */
export const emailChange = sqliteTable('email_change', {
  userId: text('user_id')
    .primaryKey()
    .references(() => user.id, { onDelete: 'cascade' }),
  newEmail: text('new_email').notNull(),
  requestedAt: integer('requested_at').notNull(),
  expiresAt: integer('expires_at').notNull(),
  /** SHA-256 of the token in the link, so a leaked database cannot be used to take over an address. */
  tokenHash: text('token_hash').notNull()
})

/** A name the person gave one of their sessions ("Work laptop"). Goes with the session or the account. */
export const sessionNickname = sqliteTable('session_nickname', {
  sessionId: text('session_id')
    .primaryKey()
    .references(() => session.id, { onDelete: 'cascade' }),
  userId: text('user_id')
    .notNull()
    .references(() => user.id, { onDelete: 'cascade' }),
  nickname: text('nickname').notNull(),
  updatedAt: integer('updated_at').notNull()
})

/** Messages people send from the web app or the desktop app. Removed with the account; included in the data export. */
export const feedback = sqliteTable(
  'feedback',
  {
    id: text('id').primaryKey(),
    userId: text('user_id')
      .notNull()
      .references(() => user.id, { onDelete: 'cascade' }),
    kind: text('kind').notNull(),
    message: text('message').notNull(),
    /** The optional diagnostics report (see the desktop app's Settings). */
    diagnostics: text('diagnostics'),
    appVersion: text('app_version'),
    platform: text('platform'),
    source: text('source').notNull(),
    createdAt: integer('created_at').notNull()
  },
  (table) => [index('feedback_user_created_idx').on(table.userId, table.createdAt)]
)

/**
 * Security events about an account (sign-ins, failures, sessions revoked, profile and passkey changes, admin actions).
 * `userId` is the person it is about; null for a failure that cannot be tied to anyone. `actorId` is who did it when
 * that is someone else (an admin), with no foreign key so it survives their own deletion. `detail` holds codes only,
 * never what a stranger typed. See audit.ts.
 */
export const auditEvent = sqliteTable(
  'audit_event',
  {
    id: text('id').primaryKey(),
    userId: text('user_id').references(() => user.id, { onDelete: 'cascade' }),
    actorId: text('actor_id'),
    type: text('type').notNull(),
    outcome: text('outcome').notNull(),
    ipAddress: text('ip_address'),
    label: text('label'),
    detail: text('detail'),
    at: integer('at').notNull()
  },
  (table) => [
    index('audit_event_user_at_idx').on(table.userId, table.at),
    index('audit_event_type_at_idx').on(table.type, table.at)
  ]
)

/**
 * Directory sync (SCIM 2.0): a company's identity provider (Okta, Entra ...) pushes its staff and groups to one team.
 * One connection per team and directory. Everything below cascades with the team, and `scim_user` also with the person.
 * We build this ourselves because Better Auth's SCIM plugin needs database transactions, which D1 does not have.
 */
export const scimConnection = sqliteTable(
  'scim_connection',
  {
    id: text('id').primaryKey(),
    organizationId: text('organization_id')
      .notNull()
      .references(() => organization.id, { onDelete: 'cascade' }),
    name: text('name').notNull(),
    createdBy: text('created_by'),
    createdAt: integer('created_at').notNull()
  },
  (table) => [index('scim_connection_org_idx').on(table.organizationId)]
)

/** A bearer token for a connection. Only a keyed hash is stored; the token is shown once. */
export const scimCredential = sqliteTable(
  'scim_credential',
  {
    id: text('id').primaryKey(),
    connectionId: text('connection_id')
      .notNull()
      .references(() => scimConnection.id, { onDelete: 'cascade' }),
    hash: text('hash').notNull(),
    /** Space separated: scim.users.read scim.users.write scim.groups.read scim.groups.write */
    scopes: text('scopes').notNull(),
    expiresAt: integer('expires_at').notNull(),
    revokedAt: integer('revoked_at'),
    lastUsedAt: integer('last_used_at'),
    createdAt: integer('created_at').notNull()
  },
  (table) => [
    uniqueIndex('scim_credential_hash_idx').on(table.hash),
    index('scim_credential_connection_idx').on(table.connectionId)
  ]
)

/** A person as the directory describes them. `userId` is the matching sign-in account. */
export const scimUser = sqliteTable(
  'scim_user',
  {
    id: text('id').primaryKey(),
    connectionId: text('connection_id')
      .notNull()
      .references(() => scimConnection.id, { onDelete: 'cascade' }),
    userId: text('user_id')
      .notNull()
      .references(() => user.id, { onDelete: 'cascade' }),
    /** True when the directory created the sign-in account (so removing the person can suspend it). */
    createdAccount: integer('created_account', { mode: 'boolean' }).notNull(),
    /** True when a group made this person a team admin, so leaving the group takes it back (and only then). */
    grantedAdmin: integer('granted_admin', { mode: 'boolean' }).notNull().default(false),
    userName: text('user_name').notNull(),
    userNameLower: text('user_name_lower').notNull(),
    externalId: text('external_id'),
    active: integer('active', { mode: 'boolean' }).notNull(),
    /** Lower-cased JSON array of every email value, for the `emails.value eq` filter. */
    emailValues: text('email_values').notNull(),
    /** The rest of the resource (name, emails, phone numbers, enterprise fields ...) as JSON. */
    data: text('data').notNull(),
    createdAt: integer('created_at').notNull(),
    updatedAt: integer('updated_at').notNull()
  },
  (table) => [
    uniqueIndex('scim_user_name_idx').on(table.connectionId, table.userNameLower),
    uniqueIndex('scim_user_external_idx').on(table.connectionId, table.externalId),
    index('scim_user_user_idx').on(table.userId)
  ]
)

/**
 * A person who deleted their account while a directory still lists them. Only a salted hash of the address is kept
 * (not the address), so the next sync does not quietly create the account again; the team owner can clear the block.
 */
export const scimTombstone = sqliteTable(
  'scim_tombstone',
  {
    id: text('id').primaryKey(),
    organizationId: text('organization_id')
      .notNull()
      .references(() => organization.id, { onDelete: 'cascade' }),
    emailHash: text('email_hash').notNull(),
    createdAt: integer('created_at').notNull()
  },
  (table) => [uniqueIndex('scim_tombstone_idx').on(table.organizationId, table.emailHash)]
)

export const scimGroup = sqliteTable(
  'scim_group',
  {
    id: text('id').primaryKey(),
    connectionId: text('connection_id')
      .notNull()
      .references(() => scimConnection.id, { onDelete: 'cascade' }),
    displayName: text('display_name').notNull(),
    displayNameLower: text('display_name_lower').notNull(),
    externalId: text('external_id'),
    /** Set by a team owner: people in this group are team admins (never owners). Off unless an owner turns it on. */
    grantsAdmin: integer('grants_admin', { mode: 'boolean' }).notNull().default(false),
    createdAt: integer('created_at').notNull(),
    updatedAt: integer('updated_at').notNull()
  },
  (table) => [
    uniqueIndex('scim_group_name_idx').on(table.connectionId, table.displayNameLower),
    uniqueIndex('scim_group_external_idx').on(table.connectionId, table.externalId)
  ]
)

export const scimGroupMember = sqliteTable(
  'scim_group_member',
  {
    groupId: text('group_id')
      .notNull()
      .references(() => scimGroup.id, { onDelete: 'cascade' }),
    scimUserId: text('scim_user_id')
      .notNull()
      .references(() => scimUser.id, { onDelete: 'cascade' })
  },
  (table) => [
    primaryKey({ columns: [table.groupId, table.scimUserId] }),
    index('scim_group_member_user_idx').on(table.scimUserId)
  ]
)
